<?php
$results=$context['results'];
$storeEnabled=Spirit\Catalog::options()['enabled'];
$labels=['all'=>'Everything','page'=>'Pages','release'=>'Music','event'=>'Shows','member'=>'Band members'];
if($storeEnabled){$labels['product']='Merchandise';}
?>
<section class="content-section search-section"><header class="content-panel content-heading"><p class="eyebrow">MUSIC · PEOPLE · PURPOSE</p><h1>Find your <em>connection.</em></h1><p class="lead"><?=$storeEnabled?'Search published music, shows, band stories and available merchandise.':'Search published music, shows and band stories.'?></p></header>
<form method="get" action="<?=e(app_url('pages/search.php'))?>" class="public-form public-filter site-search"><label for="site-search-query">Search the website<input id="site-search-query" name="q" type="search" value="<?=e($results['q'])?>" maxlength="100" required></label><label for="site-search-kind">Look in<select id="site-search-kind" name="kind"><?php foreach($labels as $value=>$label):?><option value="<?=e($value)?>" <?=$results['kind']===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><button class="button">Search</button></form>
<?php if($context['error']??null):?><p class="form-notice error" role="alert"><?=e($context['error'])?></p><?php endif;?>
<?php if($results['q']===''):?><div class="empty-state"><h2>What are you looking for?</h2><p><?=$storeEnabled?'Enter a song release, show, band member, story or product name.':'Enter a song release, show, band member or story.'?></p></div><?php else:?><p class="small muted" role="status"><?=number_format($results['total'])?> result(s) for “<?=e($results['q'])?>” · Page <?=$results['page']?> of <?=$results['pages']?></p><div class="search-results"><?php foreach($results['items'] as $result):?><article><p class="eyebrow"><?=e($labels[$result['kind']]??'Website')?></p><h2><a href="<?=e($result['url'])?>"><?=e($result['title'])?></a></h2><p><?=e($result['summary'])?></p><a class="text-link" href="<?=e($result['url'])?>">Explore →</a></article><?php endforeach;?></div><?php if(!$results['items']):?><div class="empty-state"><h2>No matches yet.</h2><p>Try a different phrase or choose another section.</p></div><?php endif;?>
<nav class="search-pagination" aria-label="Search result pages"><?php if($results['page']>1):?><a class="button secondary" rel="prev" href="<?=e(app_url('pages/search.php?'.http_build_query(['q'=>$results['q'],'kind'=>$results['kind'],'page'=>$results['page']-1])))?>">← Previous</a><?php endif;?><?php if($results['page']<$results['pages']):?><a class="button secondary" rel="next" href="<?=e(app_url('pages/search.php?'.http_build_query(['q'=>$results['q'],'kind'=>$results['kind'],'page'=>$results['page']+1])))?>">Next →</a><?php endif;?></nav><?php endif;?></section>
